def _p1_d6_832_product(a,b,out,binding):
    """Fixed serial-top D6, then the exact current top reconstruction."""
    assert len(a.shape)==len(b.shape)==len(out.shape)==2
    assert str(a.dtype)==str(b.dtype)==str(out.dtype)=="float32"
